func judgePoint24(nums []int) bool {
	a := make([]float64, len(nums))
	for i, x := range nums {
		a[i] = float64(x)
	}
	var solve func(arr []float64) bool
	solve = func(arr []float64) bool {
		if len(arr) == 1 {
			return math.Abs(arr[0]-24) < 1e-6
		}
		for i := 0; i < len(arr); i++ {
			for j := 0; j < len(arr); j++ {
				if i == j {
					continue
				}
				rest := []float64{}
				for k := 0; k < len(arr); k++ {
					if k != i && k != j {
						rest = append(rest, arr[k])
					}
				}
				x, y := arr[i], arr[j]
				cands := []float64{x + y, x - y, x * y}
				if math.Abs(y) > 1e-6 {
					cands = append(cands, x/y)
				}
				for _, v := range cands {
					next := append(append([]float64{}, rest...), v)
					if solve(next) {
						return true
					}
				}
			}
		}
		return false
	}
	return solve(a)
}

class Solution {
  public boolean judgePoint24(int[] nums) {
    double[] a = new double[nums.length];
    for (int i = 0; i < nums.length; i++) {
      a[i] = nums[i];
    }
    return solve(a);
  }

  private boolean solve(double[] a) {
    if (a.length == 1) {
      return Math.abs(a[0] - 24) < 1e-6;
    }
    for (int i = 0; i < a.length; i++) {
      for (int j = 0; j < a.length; j++) {
        if (i == j) {
          continue;
        }
        double[] rest = new double[a.length - 2];
        int t = 0;
        for (int k = 0; k < a.length; k++) {
          if (k != i && k != j) {
            rest[t++] = a[k];
          }
        }
        double x = a[i], y = a[j];
        double[] cands = { x + y, x - y, x * y };
        for (double v : cands) {
          if (next(rest, v)) {
            return true;
          }
        }
        if (Math.abs(y) > 1e-6 && next(rest, x / y)) {
          return true;
        }
      }
    }
    return false;
  }

  private boolean next(double[] rest, double v) {
    double[] nb = new double[rest.length + 1];
    System.arraycopy(rest, 0, nb, 0, rest.length);
    nb[rest.length] = v;
    return solve(nb);
  }
}

class Solution:
    def judgePoint24(self, nums: List[int]) -> bool:
        def solve(arr):
            if len(arr) == 1:
                return abs(arr[0] - 24) < 1e-6
            for i in range(len(arr)):
                for j in range(len(arr)):
                    if i == j:
                        continue
                    rest = [arr[k] for k in range(len(arr)) if k != i and k != j]
                    x, y = arr[i], arr[j]
                    cands = [x + y, x - y, x * y]
                    if abs(y) > 1e-6:
                        cands.append(x / y)
                    for v in cands:
                        if solve(rest + [v]):
                            return True
            return False

        return solve([float(x) for x in nums])

const judgePoint24 = (nums: number[]): boolean => {
  const solve = (arr: number[]): boolean => {
    if (arr.length === 1) return Math.abs(arr[0] - 24) < 1e-6;
    for (let i = 0; i < arr.length; i++) {
      for (let j = 0; j < arr.length; j++) {
        if (i === j) continue;
        const rest: number[] = [];
        for (let k = 0; k < arr.length; k++) {
          if (k !== i && k !== j) rest.push(arr[k]);
        }
        const x = arr[i];
        const y = arr[j];
        const cands = [x + y, x - y, x * y];
        if (Math.abs(y) > 1e-6) cands.push(x / y);
        for (const v of cands) {
          if (solve([...rest, v])) return true;
        }
      }
    }
    return false;
  };
  return solve(nums.map((x) => x));
};
